  "Signs of dying (falling blood pressure, cold mottled hands and feet, jaw breathing, Cheyne–Stokes breathing, little urine) mean this plan needs urgent review. If the signs are unclear, get a second opinion — wrongly deciding someone is dying can make it come true.": "ಸಾವಿನ ಲಕ್ಷಣಗಳು (ರಕ್ತದೊತ್ತಡ ಇಳಿಯುವುದು, ತಣ್ಣಗಾದ ಕಲೆಕಲೆಯಾದ ಕೈಕಾಲುಗಳು, ದವಡೆಯಿಂದ ಉಸಿರಾಟ, ಚೇನ್–ಸ್ಟೋಕ್ಸ್ ಉಸಿರಾಟ, ತುಂಬಾ ಕಡಿಮೆ ಮೂತ್ರ) ಕಂಡರೆ ಈ ಯೋಜನೆಯನ್ನು ತುರ್ತಾಗಿ ಪರಿಶೀಲಿಸಬೇಕು. ಲಕ್ಷಣಗಳು ಸ್ಪಷ್ಟವಿಲ್ಲದಿದ್ದರೆ, ಇನ್ನೊಬ್ಬರ ಅಭಿಪ್ರಾಯ ಪಡೆಯಿರಿ — ಯಾರಾದರೂ ಸಾಯುತ್ತಿದ್ದಾರೆ ಎಂದು ತಪ್ಪಾಗಿ ನಿರ್ಧರಿಸಿದರೆ ಅದು ನಿಜವೇ ಆಗಬಹುದು.",
