  "Attested by (notary or gazetted officer)": "ದೃಢೀಕರಿಸಿದವರು (ನೋಟರಿ ಅಥವಾ ಗೆಜೆಟೆಡ್ ಅಧಿಕಾರಿ)",
  "AUDIT-values": "ಚಿಕಿತ್ಸೆಯ ಮಿತಿಗಳನ್ನು ತುಂಬಲಾಗಿದೆ, ಆದರೆ ರೋಗಿಯ ಮೌಲ್ಯಗಳು ಖಾಲಿ ಇವೆ. ರೋಗಿಗೆ ಯಾವುದು ಮುಖ್ಯ ಎಂದು ಅವರದೇ ಮಾತುಗಳಲ್ಲಿ ಬರೆಯಿರಿ.",
  "B · Balanced: treat within limits": "B · ಸಮತೋಲಿತ: ಮಿತಿಯೊಳಗೆ ಚಿಕಿತ್ಸೆ",
