  "C4-ng-duration": "ಪರಿಶೀಲನೆಗೆ ಮೊದಲು ಮೂಗಿನ ನಳಿಕೆಯನ್ನು (NG) ಎಷ್ಟು ದಿನ ಪ್ರಯತ್ನಿಸಬೇಕು ಎಂದು ಬರೆಯಿರಿ (1 ಅಥವಾ ಹೆಚ್ಚು).",
