  "Cancel the advance care plan": "ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ ರದ್ದುಪಡಿಸಿ",
  "Cancel this plan": "ಈ ಯೋಜನೆಯನ್ನು ರದ್ದುಪಡಿಸಿ",
  "Cancel version {0}": "ಆವೃತ್ತಿ {0} ರದ್ದುಪಡಿಸಿ",
  "Cancelled": "ರದ್ದಾಗಿದೆ",
  "Cancelled in writing": "ಬರವಣಿಗೆಯಲ್ಲಿ ರದ್ದುಪಡಿಸಲಾಗಿದೆ",
  "Cancelling withdraws the emergency card. Emergency teams will then give full standard care until a new plan is signed.": "ರದ್ದುಪಡಿಸಿದರೆ ತುರ್ತು ಕಾರ್ಡ್ ಹಿಂಪಡೆಯಲಾಗುತ್ತದೆ. ನಂತರ ಹೊಸ ಯೋಜನೆಗೆ ಸಹಿ ಆಗುವವರೆಗೆ ತುರ್ತು ತಂಡಗಳು ಪೂರ್ಣ ಸಾಮಾನ್ಯ ಚಿಕಿತ್ಸೆ ನೀಡುತ್ತವೆ.",
  "Cannot make this decision now": "ಈಗ ಈ ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳಲು ಆಗುವುದಿಲ್ಲ",
  "CAP-assessment": "ರೋಗಿಯ ನಿರ್ಧರಿಸುವ ಸಾಮರ್ಥ್ಯವನ್ನು ಯಾರು ಪರಿಶೀಲಿಸಿದರು, ದಿನಾಂಕ, ಮತ್ತು ಹೇಗೆ ನಿರ್ಣಯಿಸಿದರು (ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದು, ನೆನಪಿಟ್ಟುಕೊಳ್ಳುವುದು, ತೂಗಿ ನೋಡುವುದು, ತಿಳಿಸುವುದು) ಎಂದು ಬರೆಯಿರಿ.",
  "CAP-missing": "ರೋಗಿ ಇಂದು ಈ ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳಬಲ್ಲರೇ ಎಂದು ದಾಖಲಿಸಿ.",
  "Capacity and advance care plan": "ನಿರ್ಧಾರ ಸಾಮರ್ಥ್ಯ ಮತ್ತು ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ",
  "Capacity assessment": "ನಿರ್ಧಾರ ಸಾಮರ್ಥ್ಯದ ಪರಿಶೀಲನೆ",
  "Card issued": "ಕಾರ್ಡ್ ನೀಡಿದ ದಿನಾಂಕ",
  "Card issued. Older cards for this patient were withdrawn.": "ಕಾರ್ಡ್ ನೀಡಲಾಗಿದೆ. ಈ ರೋಗಿಯ ಹಳೆಯ ಕಾರ್ಡ್‌ಗಳನ್ನು ಹಿಂಪಡೆಯಲಾಗಿದೆ.",
  "Card lost or replaced": "ಕಾರ್ಡ್ ಕಳೆದುಹೋಗಿದೆ ಅಥವಾ ಬದಲಿಸಲಾಗಿದೆ",
  "CARD WITHDRAWN": "ಕಾರ್ಡ್ ಹಿಂಪಡೆಯಲಾಗಿದೆ",
  "Card withdrawn. Its QR now shows \"card withdrawn\".": "ಕಾರ್ಡ್ ಹಿಂಪಡೆಯಲಾಗಿದೆ. ಇದರ QR ಈಗ “ಕಾರ್ಡ್ ಹಿಂಪಡೆಯಲಾಗಿದೆ” ಎಂದು ತೋರಿಸುತ್ತದೆ.",
  "Care plan": "ಆರೈಕೆ ಯೋಜನೆ",
  "Care that always continues": "ಯಾವಾಗಲೂ ಮುಂದುವರಿಯುವ ಆರೈಕೆ",
  "Change it": "ಇದನ್ನು ಬದಲಿಸಿ",
  "Changes make a new version that must be printed, signed and attested again. Version {0} stays current until then.": "ಬದಲಾವಣೆಗಳಿಂದ ಹೊಸ ಆವೃತ್ತಿ ಸಿದ್ಧವಾಗುತ್ತದೆ; ಅದನ್ನು ಮತ್ತೆ ಮುದ್ರಿಸಿ, ಸಹಿ ಮಾಡಿ, ದೃಢೀಕರಿಸಬೇಕು. ಅಲ್ಲಿಯವರೆಗೆ ಆವೃತ್ತಿ {0} ಪ್ರಸ್ತುತವಾಗಿರುತ್ತದೆ.",
  "Check": "ಪರಿಶೀಲಿಸಿ",
  "Check again on": "ಮತ್ತೆ ಪರಿಶೀಲಿಸುವ ದಿನಾಂಕ",
  "Check and print": "ಪರಿಶೀಲಿಸಿ ಮುದ್ರಿಸಿ",
  "Check it now, for this decision. Do not use old notes.": "ಈ ನಿರ್ಧಾರಕ್ಕಾಗಿ ಈಗಲೇ ಪರಿಶೀಲಿಸಿ. ಹಳೆಯ ಟಿಪ್ಪಣಿಗಳನ್ನು ಬಳಸಬೇಡಿ.",
  "Check the paper copy against the scan and its SHA-256, or with the custodian. Doctors only read this here; nothing in the app starts or stops treatment.": "ಕಾಗದದ ಪ್ರತಿಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮತ್ತು ಅದರ SHA-256 ಜೊತೆ, ಅಥವಾ ಸಂರಕ್ಷಕರೊಂದಿಗೆ ಹೋಲಿಸಿ ನೋಡಿ. ಡಾಕ್ಟರ್‌ಗಳು ಇದನ್ನು ಇಲ್ಲಿ ಓದುತ್ತಾರೆ ಮಾತ್ರ; ಆ್ಯಪ್‌ನಲ್ಲಿರುವ ಯಾವುದೂ ಚಿಕಿತ್ಸೆಯನ್ನು ಆರಂಭಿಸುವುದಿಲ್ಲ ಅಥವಾ ನಿಲ್ಲಿಸುವುದಿಲ್ಲ.",
  "Checked on": "ಪರಿಶೀಲಿಸಿದ ದಿನಾಂಕ",
  "Choose": "ಆಯ್ಕೆ ಮಾಡಿ",
  "Choose a patient first.": "ಮೊದಲು ರೋಗಿಯನ್ನು ಆಯ್ಕೆ ಮಾಡಿ.",
  "Clinical reason": "ಕ್ಲಿನಿಕಲ್ ಕಾರಣ",
  "Co-signature (palliative clinician or nurse)": "ಸಹ-ಸಹಿ (ಪ್ಯಾಲಿಯೇಟಿವ್ ಡಾಕ್ಟರ್ ಅಥವಾ ನರ್ಸ್)",
  "Comfort care, pain relief, mouth care and feeding by mouth always continue. This cannot be changed.": "ಆರಾಮದ ಆರೈಕೆ, ನೋವು ನಿವಾರಣೆ, ಬಾಯಿಯ ಆರೈಕೆ ಮತ್ತು ಬಾಯಿಯ ಮೂಲಕ ಆಹಾರ ಯಾವಾಗಲೂ ಮುಂದುವರಿಯುತ್ತವೆ. ಇದನ್ನು ಬದಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "Comfort care, pain relief, mouth care, feeding by mouth": "ಆರಾಮದ ಆರೈಕೆ, ನೋವು ನಿವಾರಣೆ, ಬಾಯಿಯ ಆರೈಕೆ, ಬಾಯಿಯ ಮೂಲಕ ಆಹಾರ",
