  "Crews resuscitate unless they are handed a signed copy of this plan.": "ಈ ಯೋಜನೆಯ ಸಹಿ ಮಾಡಿದ ಪ್ರತಿಯನ್ನು ಕೈಗೆ ನೀಡದಿದ್ದರೆ ತಂಡಗಳು ಪುನರುಜ್ಜೀವನ (CPR) ಮಾಡುತ್ತವೆ.",
