  "Live link is on the Sahara server. A copy is also saved on this device for offline use.": "ಲೈವ್ ಲಿಂಕ್ ಸಹಾರಾ ಸರ್ವರ್‌ನಲ್ಲಿದೆ. ಆಫ್‌ಲೈನ್ ಬಳಕೆಗಾಗಿ ಒಂದು ಪ್ರತಿಯನ್ನು ಈ ಸಾಧನದಲ್ಲೂ ಉಳಿಸಲಾಗಿದೆ.",
