  "Name at least one, better two, people who can speak for you (representatives).": "ನಿಮ್ಮ ಪರವಾಗಿ ಮಾತನಾಡಬಲ್ಲ ಕನಿಷ್ಠ ಒಬ್ಬರನ್ನು, ಸಾಧ್ಯವಾದರೆ ಇಬ್ಬರನ್ನು (ಪ್ರತಿನಿಧಿಗಳು) ಹೆಸರಿಸಿ.",
  "Name of the place": "ಸ್ಥಳದ ಹೆಸರು",
  "Name you want to be called": "ನಿಮ್ಮನ್ನು ಕರೆಯಬೇಕಾದ ಹೆಸರು",
  "Named by the patient (no advance care plan)": "ರೋಗಿ ಹೆಸರಿಸಿದವರು (ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ ಇಲ್ಲ)",
  "Named in a signed advance care plan (AMD)": "ಸಹಿ ಮಾಡಿದ ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ‌ನಲ್ಲಿ (AMD) ಹೆಸರಿಸಲಾಗಿದೆ",
  "Need to change something? Start a new version from the signed one below, or ask for help. This printed copy must then not be signed.": "ಏನಾದರೂ ಬದಲಿಸಬೇಕೇ? ಕೆಳಗಿನ ಸಹಿ ಮಾಡಿದ ಆವೃತ್ತಿಯಿಂದ ಹೊಸ ಆವೃತ್ತಿ ಆರಂಭಿಸಿ, ಅಥವಾ ಸಹಾಯ ಕೇಳಿ. ಆಗ ಈ ಮುದ್ರಿತ ಪ್ರತಿಗೆ ಸಹಿ ಮಾಡಬಾರದು.",
  "Never enter the full Aadhaar or ID number.": "ಪೂರ್ಣ ಆಧಾರ್ ಅಥವಾ ಗುರುತಿನ ಸಂಖ್ಯೆಯನ್ನು ಎಂದಿಗೂ ನಮೂದಿಸಬೇಡಿ.",
  "Never type the full number here. Write it by hand on the paper.": "ಪೂರ್ಣ ಸಂಖ್ಯೆಯನ್ನು ಇಲ್ಲಿ ಎಂದಿಗೂ ಟೈಪ್ ಮಾಡಬೇಡಿ. ಅದನ್ನು ಕಾಗದದ ಮೇಲೆ ಕೈಯಿಂದ ಬರೆಯಿರಿ.",
  "Next of kin, next friend or guardian": "ಹತ್ತಿರದ ಸಂಬಂಧಿ, ಆಪ್ತರು ಅಥವಾ ಪೋಷಕರು",
  "NIV trial: up to how many hours": "NIV ಪ್ರಯೋಗ: ಗರಿಷ್ಠ ಎಷ್ಟು ಗಂಟೆಗಳು",
  "NIV up to {0} hours": "NIV {0} ಗಂಟೆಗಳವರೆಗೆ",
  "No — care where they are": "ಇಲ್ಲ — ಇರುವಲ್ಲೇ ಆರೈಕೆ",
  "No connection to the Sahara server — showing the copy saved on this phone when the card was issued.": "ಸಹಾರಾ ಸರ್ವರ್‌ಗೆ ಸಂಪರ್ಕವಿಲ್ಲ — ಕಾರ್ಡ್ ನೀಡಿದಾಗ ಈ ಫೋನ್‌ನಲ್ಲಿ ಉಳಿಸಿದ ಪ್ರತಿಯನ್ನು ತೋರಿಸಲಾಗುತ್ತಿದೆ.",
  "No emergency care plan yet. A card can be made once the treating consultant signs the plan.": "ಇನ್ನೂ ತುರ್ತು ಆರೈಕೆ ಯೋಜನೆ ಇಲ್ಲ. ಚಿಕಿತ್ಸೆ ನೀಡುವ ಕನ್ಸಲ್ಟೆಂಟ್ ಯೋಜನೆಗೆ ಸಹಿ ಮಾಡಿದ ನಂತರ ಕಾರ್ಡ್ ಮಾಡಬಹುದು.",
  "No advance care plan": "ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ ಇಲ್ಲ",
  "No advance care plan is recorded in Sahara. Ask the family if a signed paper exists.": "ಸಹಾರಾದಲ್ಲಿ ಯಾವುದೇ ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ ದಾಖಲಾಗಿಲ್ಲ. ಸಹಿ ಮಾಡಿದ ಕಾಗದ ಇದೆಯೇ ಎಂದು ಕುಟುಂಬವನ್ನು ಕೇಳಿ.",
  "No plan yet": "ಇನ್ನೂ ಯೋಜನೆ ಇಲ್ಲ",
  "No preference": "ಯಾವುದೇ ಆದ್ಯತೆ ಇಲ್ಲ",
  "No preference recorded — standard care": "ಯಾವುದೇ ಆದ್ಯತೆ ದಾಖಲಾಗಿಲ್ಲ — ಸಾಮಾನ್ಯ ಚಿಕಿತ್ಸೆ",
  "No signed advance care plan recorded yet": "ಇನ್ನೂ ಸಹಿ ಮಾಡಿದ ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ ದಾಖಲಾಗಿಲ್ಲ",
  "No versions yet.": "ಇನ್ನೂ ಯಾವುದೇ ಆವೃತ್ತಿ ಇಲ್ಲ.",
  "Nobody may pressure you. You can change or cancel it at any time, in writing.": "ಯಾರೂ ನಿಮ್ಮ ಮೇಲೆ ಒತ್ತಡ ಹೇರುವಂತಿಲ್ಲ. ಇದನ್ನು ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ, ಬರವಣಿಗೆಯಲ್ಲಿ, ಬದಲಿಸಬಹುದು ಅಥವಾ ರದ್ದುಪಡಿಸಬಹುದು.",
  "Nose tube (NG)": "ಮೂಗಿನ ನಳಿಕೆ (NG)",
  "Nose tube feeding (NG)": "ಮೂಗಿನ ನಳಿಕೆಯ ಮೂಲಕ ಆಹಾರ (NG)",
  "Not a valid plan — give standard care": "ಮಾನ್ಯ ಯೋಜನೆಯಲ್ಲ — ಸಾಮಾನ್ಯ ಚಿಕಿತ್ಸೆ ನೀಡಿ",
  "Not acceptable to the patient": "ರೋಗಿಗೆ ಒಪ್ಪಿಗೆಯಿಲ್ಲದ್ದು",
  "Not added yet.": "ಇನ್ನೂ ಸೇರಿಸಿಲ್ಲ.",
