  "on": "ದಿನಾಂಕ",
  "Once printed, this version cannot be changed in the app. To change anything, start a new version and print again.": "ಮುದ್ರಿಸಿದ ನಂತರ ಈ ಆವೃತ್ತಿಯನ್ನು ಆ್ಯಪ್‌ನಲ್ಲಿ ಬದಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಏನಾದರೂ ಬದಲಿಸಲು ಹೊಸ ಆವೃತ್ತಿ ಆರಂಭಿಸಿ ಮತ್ತೆ ಮುದ್ರಿಸಿ.",
  "Oncologist or treating doctor": "ಕ್ಯಾನ್ಸರ್ ತಜ್ಞರು ಅಥವಾ ಚಿಕಿತ್ಸೆ ನೀಡುವ ಡಾಕ್ಟರ್",
  "Only {0} can make and sign an advance care plan, in their own words. You can help them fill it in and read it out to them.": "{0} ಅವರು ಮಾತ್ರ ತಮ್ಮದೇ ಮಾತುಗಳಲ್ಲಿ ಮುಂಗಡ ಆರೈಕೆ ಯೋಜನೆ ಮಾಡಿ ಸಹಿ ಮಾಡಬಹುದು. ಅದನ್ನು ತುಂಬಲು ಮತ್ತು ಅವರಿಗೆ ಓದಿ ಹೇಳಲು ನೀವು ಸಹಾಯ ಮಾಡಬಹುದು.",
  "Only after a talk with the palliative care team": "ಪ್ಯಾಲಿಯೇಟಿವ್ ಆರೈಕೆ ತಂಡದೊಂದಿಗೆ ಮಾತನಾಡಿದ ನಂತರ ಮಾತ್ರ",
  "Only for adults, 18 or older.": "ವಯಸ್ಕರಿಗೆ ಮಾತ್ರ, 18 ಅಥವಾ ಹೆಚ್ಚು ವರ್ಷ.",
  "Only for the reasons ticked below": "ಕೆಳಗೆ ಗುರುತಿಸಿದ ಕಾರಣಗಳಿಗೆ ಮಾತ್ರ",
