  "Open full record": "ಪೂರ್ಣ ದಾಖಲೆ ತೆರೆಯಿರಿ",
  "Open the review draft": "ಪರಿಶೀಲನಾ ಕರಡು ತೆರೆಯಿರಿ",
  "Opened": "ತೆರೆಯಲಾಗಿದೆ",
  "Opening the emergency card…": "ತುರ್ತು ಕಾರ್ಡ್ ತೆರೆಯುತ್ತಿದೆ…",
  "Opening the full record is logged with your reason, and the primary decision-maker is sent an SMS where SMS is set up.": "ಪೂರ್ಣ ದಾಖಲೆ ತೆರೆದರೆ ನಿಮ್ಮ ಕಾರಣದೊಂದಿಗೆ ಲಾಗ್ ಆಗುತ್ತದೆ, ಮತ್ತು SMS ವ್ಯವಸ್ಥೆ ಇದ್ದಲ್ಲಿ ಮುಖ್ಯ ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುವವರಿಗೆ SMS ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
  "Opening…": "ತೆರೆಯುತ್ತಿದೆ…",
