  "Phone numbers to call before an ambulance (one per line)": "ಆಂಬ್ಯುಲೆನ್ಸ್‌ಗೆ ಮೊದಲು ಕರೆ ಮಾಡಬೇಕಾದ ಫೋನ್ ಸಂಖ್ಯೆಗಳು (ಪ್ರತಿ ಸಾಲಿಗೆ ಒಂದು)",
