  "Plays on this device": "ಈ ಸಾಧನದಲ್ಲೇ ಪ್ಲೇ ಆಗುತ್ತದೆ",
  "Please confirm": "ದಯವಿಟ್ಟು ದೃಢಪಡಿಸಿ",
  "Please fix the items marked above to continue.": "ಮುಂದುವರಿಯಲು ಮೇಲೆ ಗುರುತಿಸಿದವನ್ನು ಸರಿಪಡಿಸಿ.",
  "Point the camera at the QR code on the card…": "ಕಾರ್ಡ್‌ನ QR ಕೋಡ್ ಕಡೆಗೆ ಕ್ಯಾಮೆರಾ ಹಿಡಿಯಿರಿ…",
  "Preferably people who are not decision-makers.": "ಇವರು ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುವವರಲ್ಲದಿದ್ದರೆ ಉತ್ತಮ.",
  "Preparing the QR code…": "QR ಕೋಡ್ ಸಿದ್ಧವಾಗುತ್ತಿದೆ…",
  "PREVIEW — NOT ISSUED": "ಮುನ್ನೋಟ — ನೀಡಿಲ್ಲ",
