  "See the plan and versions": "ಯೋಜನೆ ಮತ್ತು ಆವೃತ್ತಿಗಳನ್ನು ನೋಡಿ",
  "Send the request": "ವಿನಂತಿ ಕಳುಹಿಸಿ",
