  "Shared": "ಹಂಚಿಕೊಳ್ಳಲಾಗಿದೆ",
  "Shocks from the device at the end of life": "ಜೀವನದ ಕೊನೆಯಲ್ಲಿ ಸಾಧನದಿಂದ ಆಘಾತಗಳು",
  "Shocks kept on": "ಆಘಾತಗಳು ಚಾಲನೆಯಲ್ಲಿರುತ್ತವೆ",
  "Shocks to be switched off": "ಆಘಾತಗಳನ್ನು ನಿಲ್ಲಿಸಬೇಕು",
  "Shown as information, not instruction.": "ಮಾಹಿತಿಯಾಗಿ ತೋರಿಸಲಾಗಿದೆ, ಸೂಚನೆಯಾಗಿ ಅಲ್ಲ.",
  "Sign": "ಸಹಿ ಮಾಡಿ",
  "Sign (or give a thumb impression) in front of two adult witnesses. Better if they are not your representatives.": "ಇಬ್ಬರು ವಯಸ್ಕ ಸಾಕ್ಷಿಗಳ ಎದುರು ಸಹಿ ಮಾಡಿ (ಅಥವಾ ಹೆಬ್ಬೆಟ್ಟಿನ ಗುರುತು ನೀಡಿ). ಅವರು ನಿಮ್ಮ ಪ್ರತಿನಿಧಿಗಳಲ್ಲದಿದ್ದರೆ ಉತ್ತಮ.",
  "Sign and make this plan active": "ಸಹಿ ಮಾಡಿ ಈ ಯೋಜನೆಯನ್ನು ಜಾರಿಗೆ ತನ್ನಿ",
