  "SMS not configured on this server, so reminders cannot be sent. Please phone them.": "ಈ ಸರ್ವರ್‌ನಲ್ಲಿ SMS ಹೊಂದಿಸಿಲ್ಲ, ಆದ್ದರಿಂದ ರಿಮೈಂಡರ್ ಕಳುಹಿಸಲು ಆಗುವುದಿಲ್ಲ. ದಯವಿಟ್ಟು ಅವರಿಗೆ ಫೋನ್ ಮಾಡಿ.",
  "SMS not configured on this server. No message was sent. Please phone them.": "ಈ ಸರ್ವರ್‌ನಲ್ಲಿ SMS ಹೊಂದಿಸಿಲ್ಲ. ಯಾವುದೇ ಸಂದೇಶ ಕಳುಹಿಸಿಲ್ಲ. ದಯವಿಟ್ಟು ಅವರಿಗೆ ಫೋನ್ ಮಾಡಿ.",
  "Spend cannot be below zero.": "ಖರ್ಚು ಸೊನ್ನೆಗಿಂತ ಕಡಿಮೆ ಇರಬಾರದು.",
  "The access log has no ED access after this arrival time.": "ಈ ಬಂದ ಸಮಯದ ನಂತರ ಪ್ರವೇಶ ಲಾಗ್‌ನಲ್ಲಿ ED ಪ್ರವೇಶ ಇಲ್ಲ.",
